package com.bank.parking;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.logging.Logger;

enum VehicleType { BIKE, CAR, TRUCK }

class ParkingSpot {
    final String id; final VehicleType size; boolean occupied;
    ParkingSpot(String id, VehicleType size) { this.id = id; this.size = size; }
}

class Ticket {
    final String ticketId; final ParkingSpot spot; final Instant entry; Instant exit;
    Ticket(String id, ParkingSpot spot) { this.ticketId = id; this.spot = spot; this.entry = Instant.now(); }
}

class ParkingFloor {
    final String name; final List<ParkingSpot> spots = new ArrayList<>();
    ParkingFloor(String name) { this.name = name; }
    synchronized ParkingSpot findNearestSpot(VehicleType type) {
        for (ParkingSpot s : spots)
            if (!s.occupied && s.size == type) { s.occupied = true; return s; }
        return null;
    }
}

interface FeeStrategy { BigDecimal fee(Duration parked); }

class HourlyFee implements FeeStrategy {
    public BigDecimal fee(Duration d) {
        long hours = Math.max(1, d.toHours());
        return new BigDecimal("50").multiply(BigDecimal.valueOf(hours));
    }
}

class ParkingLot {
    private static final Logger log = Logger.getLogger("PARK");
    private final List<ParkingFloor> floors; private final FeeStrategy feeStrategy;
    private int counter = 0;
    ParkingLot(List<ParkingFloor> floors, FeeStrategy fee) { this.floors = floors; this.feeStrategy = fee; }

    Ticket park(VehicleType type, String vehicleNo) {
        for (ParkingFloor f : floors) {
            ParkingSpot spot = f.findNearestSpot(type);
            if (spot != null) {
                Ticket t = new Ticket("TKT-" + (++counter), spot);
                log.info(() -> vehicleNo + " parked at " + spot.id);
                return t;
            }
        }
        throw new IllegalStateException("Lot full for " + type);
    }

    BigDecimal exit(Ticket t) {
        t.exit = Instant.now();
        t.spot.occupied = false;
        BigDecimal fee = feeStrategy.fee(Duration.between(t.entry, t.exit));
        log.info(() -> "Exit " + t.ticketId + " fee=" + fee);
        return fee;
    }
}

public class ParkingDemo {
    public static void main(String[] args) {
        ParkingFloor f1 = new ParkingFloor("F1");
        f1.spots.add(new ParkingSpot("F1-C1", VehicleType.CAR));
        f1.spots.add(new ParkingSpot("F1-B1", VehicleType.BIKE));
        ParkingLot lot = new ParkingLot(List.of(f1), new HourlyFee());
        Ticket rajesh = lot.park(VehicleType.CAR, "MH01-RAJESH");
        Ticket priya  = lot.park(VehicleType.BIKE, "MH02-PRIYA");
        lot.exit(rajesh);
        lot.exit(priya);
    }
}
